Convert SQL to PySpark:
```sql
select *
from (
    select *, row_number() over (partition by delta_greenhouse order by cruiser_grade, id) as rnk
    from districts
    where cruiser_grade < 41
) as t
where rnk <= 3;
```

Convert SQL to PySpark:
```sql
select *
from (
    select case when lane_throughput >= 261 then 'high' when lane_throughput >= 84 then 'mid' else 'low' end as lane_throughput_bucket, sum(lane_throughput) as total_lane_throughput, min(lane_throughput) as inland_cooler
    from statue_blimps
    group by case when lane_throughput >= 261 then 'high' when lane_throughput >= 84 then 'mid' else 'low' end
) as agg
where total_lane_throughput >= 1130;
```

Convert SQL to PySpark:
```sql
select id, hotel_id, checkout_day
from (
    select *, dense_rank() over (partition by hotel_id order by checkout_day desc) rn
    from housekeeping_tasks
) r
where rn <= 2;
```
